 "b-01-004": {
  "c": "職業災害死亡補償為40個月平均工資，另加5個月喪葬費。",
  "w": {
   "1": "職業災害死亡補償為40個月，非30個月。",
   "3": "職業災害死亡補償為40個月，非50個月。",
   "4": "職業災害死亡補償為40個月，非60個月。"
  },
  "ref": "勞動基準法§第59條",
  "law": "《勞動基準法》第59條：勞工因遭遇職業災害而致死亡、失能、傷害或疾病時，雇主應依下列規定予以補償。但如同一事故，依勞工保險條例或其他法令規定，已由雇主支付費用補償者，雇主得予以抵充之：\n\n一、勞工受傷或罹患職業病時，雇主應補償其必需之醫療費用。職業病之種類及其醫療範圍，依勞工保險條例有關之規定。\n\n二、勞工在醫療中不能工作時，雇主應按其原領工資數額予以補償。但醫療期間屆滿二年仍未能痊癒，經指定之醫院診斷，審定為喪失原有工作能力，且不合第三款之失能給付標準者，雇主得一次給付四十個月之平均工資後，免除此項工資補償責任。\n\n三、勞工經治療終止後，經指定之醫院診斷，審定其遺存障害者，雇主應按其平均工資及其失能程度，一次給予失能補償。失能補償標準，依勞工保險條例有關之規定。\n\n四、勞工遭遇職業傷害或罹患職業病而死亡時，雇主除給與五個月平均工資之喪葬費外，並應一次給與其遺屬四十個月平均工資之死亡補償。其遺屬受領死亡補償之順位如下：\n\n（一）配偶及子女。\n\n（二）父母。\n\n（三）祖父母。\n\n（四）孫子女。\n\n（五）兄弟姐妹。",
  "g": 1
 },
