  "ref": "勞動檢查法§第3條",
  "law": "《勞動檢查法》第3條：本法用詞定義如下：\n\n一、勞動檢查機構：指中央或直轄市主管機關或有關機關為辦理勞動檢查業務所設置之專責檢查機構。\n\n二、代行檢查機構：指由中央主管機關指定為辦理危險性機械或設備檢查之行政機關、學術機構或非營利法人。\n\n三、勞動檢查員：指領有勞動檢查證執行勞動檢查職務之人員。\n\n四、代行檢查員：指領有代行檢查證執行代行檢查職務之人員。",
