  "ref": "勞動檢查法§第4條",
  "law": "《勞動檢查法》第4條：勞動檢查事項範圍如下：\n\n一、依本法規定應執行檢查之事項。\n\n二、勞動基準法令規定之事項。\n\n三、職業安全衛生法令規定之事項。\n\n四、其他依勞動法令應辦理之事項。",
