  "ref": "勞動檢查法§第25條",
  "law": "《勞動檢查法》第25條：勞動檢查員對於事業單位之檢查結果，應報由所屬勞動檢查機構依法處理；其有違反勞動法令規定事項者，勞動檢查機構並應於十日內以書面通知事業單位立即改正或限期改善，並副知直轄市、縣（市）主管機關督促改善。對公營事業單位檢查之結果，應另副知其目的事業主管機關督促其改善。\n\n事業單位對前項檢查結果，應於違規場所顯明易見處公告七日以上。",
