  "ref": "職業安全衛生設施規則§第259條",
  "law": "《職業安全衛生設施規則》第259條：雇主使勞工於接近高壓電路或高壓電路支持物從事敷設、檢查、修理、油漆等作業時，為防止勞工接觸高壓電路引起感電之危險，在距離頭上、身側及腳下六十公分以內之高壓電路者，應在該電路設置絕緣用防護裝備。但已使該作業勞工戴用絕緣用防護具而無感電之虞者，不在此限。",
