  "ref": "職業安全衛生設施規則§第295條之1",
  "law": "《職業安全衛生設施規則》第295條之1：雇主使勞工從事畜牧、動物養殖、農作物耕作、採收、園藝、綠化服務、田野調查、量測或其他易與動、植物接觸之作業，有造成勞工傷害或感染之虞者，應採取危害預防或隔離設施、提供適當之防衛裝備或個人防護器具。",
  "g": 1
