  "ref": "職業安全衛生設施規則§第311條",
  "law": "《職業安全衛生設施規則》第311條：雇主對於勞工經常作業之室內作業場所，其窗戶及其他開口部分等可直接與大氣相通之開口部分面積，應為地板面積之二十分之一以上。但設置具有充分換氣能力之機械通風設備者，不在此限。\n\n雇主對於前項室內作業場所之氣溫在攝氏十度以下換氣時，不得使勞工暴露於每秒一公尺以上之氣流中。",
