  "ref": "優先管理化學品之指定及運作管理辦法§第7條",
  "law": "《優先管理化學品之指定及運作管理辦法》第7條：運作者對於前條之優先管理化學品，應檢附下列資料報請中央主管機關首次備查：\n\n一、運作者基本資料，如附表四。\n\n二、優先管理化學品運作資料，如附表五。\n\n三、其他中央主管機關指定公告之資料。\n\n前項報請首次備查之期限如下：\n\n一、運作者勞工人數達一百人以上：應於中央主管機關公告生效日起六個月內。\n\n二、運作者勞工人數未滿一百人：應於中央主管機關公告生效日起十二個月內。",
