  "ref": "重體力勞動作業勞工保護措施標準§第5條",
  "law": "《重體力勞動作業勞工保護措施標準》第5條：雇主使勞工從事重體力勞動作業時，應充分供應飲用水及食鹽，並採取必要措施指導勞工避免重體力勞動之危害。",
  "g": 1
